INSERT INTO `services` (`id`, `title`, `slug`, `category`, `icon`, `image`, `short_description`, `full_description`, `meta_title`, `meta_description`, `is_featured`, `is_active`, `sort_order`, `created_at`, `updated_at`) VALUES
(2, 'Hair Transplant', 'hair-transplant', 'hair', 'hair', 'services/hair-transplant.webp', 'Surgical hair restoration moves follicles from a donor area to areas affected by hair loss.', '<p>Hair transplantation moves follicles from a donor area to areas with thinning or hair loss. A consultation assesses the pattern and cause of hair loss, donor hair availability, health factors, and likely goals before surgery is considered.</p><h2>Procedure and recovery</h2><p>The source clinic describes FUE, FUT, and direct-transplant techniques, with procedures lasting several hours depending on the plan. Recovery and growth timelines vary; visible growth takes months, and a fuller result may take about a year.</p><h2>Planning your treatment</h2><p>Your surgeon should discuss risks, aftercare, expected density, and the possibility of ongoing hair loss before proceeding. Individual outcomes cannot be guaranteed.</p>', 'Hair Transplant | Aakar Dermatology', 'Learn about hair transplant assessment, techniques, and recovery at Aakar Dermatology in Lalitpur.', 0, 1, 15, '2026-09-18 20:10:23', '2026-10-02 10:55:48'),
(3, 'Asian Eyelid Surgery or Blepharoplasty - Dr.Rajan Tajhya | Aakar Dermatology', 'asian-eyelid-surgery-or-blepharoplasty', 'skin', 'skin', 'services/asian-eyelid-surgery-or-blepharoplasty-13c26d018938a8bb.png', 'Achieve fuller, bigger eyes with Asian Eyelid Surgery in Nepal. This one-hour procedure offers a permanent solution for easier eyeliner.', '<div><!-- primary start -->\r\n\r\n						\n<article>\n\n	<div>\n\n		<img width=\"640\" height=\"229\" src=\"http://localhost:8000/storage/services/asian-eyelid-surgery-or-blepharoplasty-13c26d018938a8bb.png\" alt=\"Asian Eyelid Surgery or Blepharoplasty\" title=\"Asian Eyelid Surgery or Blepharoplasty\" srcset=\"http://localhost:8000/storage/services/asian-eyelid-surgery-or-blepharoplasty-13c26d018938a8bb.png 1024w, http://localhost:8000/storage/services/asian-eyelid-surgery-or-blepharoplasty-1fcea64cbfe6f794.png 300w, http://localhost:8000/storage/services/asian-eyelid-surgery-or-blepharoplasty-4a220742a6f0de0c.png 768w, http://localhost:8000/storage/services/asian-eyelid-surgery-or-blepharoplasty-601ff3a8dad6e4fe.png 1120w\">\n		<header>\n			<h3>Asian Eyelid Surgery or Blepharoplasty</h3>		</header><!-- .entry-header -->\n\n				<div>\n						<section>\n						<div>\n					<div>\n			<div>\n						<div>\n				<div>\n									<p>Most ladies use eyelid sticker to be able to put eyeliners while doing their makeup. With this one-hour procedure (Asian Eyelid Surgery), the problem will be solved permanently.</p><p>Asian eyelid surgery is one of the most common <a href=\"https://drrajanskinclinic.com/package-price/#cosmetic-surgery\">cosmetic procedures</a> we perform in our clinic. The primary purpose is to create a space for Mongolian eyes so that they can put an eyeliner. As the name suggests, the <a href=\"https://akarshanskin.com/\">surgery</a> is mainly done by Mongolians or Asians to have fuller, bigger eyes.</p><h2>What is the price of Asian Eye Lid Surgery in Lalitpur, Kathmandu, Nepal</h2><p><b>The price of Asian Eye Lid Surgery in Lalitpur, Kathmandu, Nepal is Rs 50000 (1 Hour)</b></p>								</div>\n				</div>\n					</div>\n		</div>\n					</div>\n		</section>\n				</div>\n		\n	</div><!-- .entry-content -->\n\n	</article><!-- #post-2766 -->\n\r\n					</div>', 'Asian Eyelid Surgery or Blepharoplasty - Dr.Rajan Tajhya | Aakar Dermatology | Dr. Rajan Tajhya Skin Clinic', 'Achieve fuller, bigger eyes with Asian Eyelid Surgery in Nepal. This one-hour procedure offers a permanent solution for easier eyeliner.', 0, 1, 23, '2026-09-18 20:10:23', '2026-10-03 11:10:03'),
(4, 'Laser Hair Reduction - Dr.Rajan Tajhya | Aakar Dermatology', 'laser-hair-reduction', 'skin', 'skin', 'services/laser-hair-reduction-e309d5e043eadda6.png', 'Laser Hair Reduction / Removal is a procedure that uses a beam of light to remove unwanted hair. Cost of laser hair removal start from 2000.', '<div><!-- primary start -->\r\n\r\n						\n<article>\n\n	<div>\n\n		<img width=\"640\" height=\"640\" src=\"http://localhost:8000/storage/services/laser-hair-reduction-e309d5e043eadda6.png\" alt=\"Laser Hair Reduction\" title=\"Laser Hair Reduction\" srcset=\"http://localhost:8000/storage/services/laser-hair-reduction-e309d5e043eadda6.png 1000w, http://localhost:8000/storage/services/laser-hair-reduction-ff04489c7266eb3d.png 300w, http://localhost:8000/storage/services/laser-hair-reduction-071f5f9a714bb342.png 150w, http://localhost:8000/storage/services/laser-hair-reduction-5c1cb6d0f661f1d0.png 768w, http://localhost:8000/storage/services/laser-hair-reduction-0120db5b978486af.png 400w\">\n		<header>\n			<h3>Laser Hair Reduction</h3>		</header><!-- .entry-header -->\n\n		\r\n<h2>What is Laser Hair Reduction / Removal?</h2>\r\n\r\n\r\n\r\n<p>Laser Hair Reduction / Removal is a procedure that uses a beam of light to remove unwanted hair. </p>\r\n\r\n\r\n\r\n<p><a href=\"https://drrajanskinclinic.com/package-price/\">The cost of Laser Hair Removal</a> is Nrs 3500 to 46000 (depending on area)</p>\r\n\r\n\r\n\r\n<p><img src=\"http://localhost:8000/storage/services/laser-hair-reduction-a8b9dbf2695e59e1.jpg\" alt=\"Laser Hair Reduction\" width=\"640\" height=\"336\"> </p>\r\n\r\n\r\n\r\n<h2>How does Laser Hair Removal work?</h2>\r\n\r\n\r\n\r\n<p>Light is absorbed by the root of the hair, Specifically melanin pigment. Light energy is converted to heat energy which damages the hair follicles. This damage to the hair follicle inhibits and delays the growth.</p>\r\n\r\n\r\n\r\n<h2>How frequently is it done?</h2>\r\n\r\n\r\n\r\n<p>Multiple sessions are required. It is done once in a month or 4 to 6 weeks gap. Hair has a cycle in the anagen phase which is the most active phase. LHR seems to be the most effective.</p>\r\n\r\n\r\n\r\n<h2>Will my hair grow?</h2>\r\n\r\n\r\n\r\n<p>Periodic maintenance sessions are required once every 6 months or a year. This is a substantial <a href=\"https://akarshanskin.com/our-services/laser-hair-removal/\">reduction</a> in hair growth, with treated areas often being nearly hair-free. Even the hair that grows back is usually fine, lighter, and less noticeable.</p>\r\n\n	</div><!-- .entry-content -->\n\n	</article><!-- #post-2721 -->\n\r\n					</div>', 'Laser Hair Reduction - Dr.Rajan Tajhya | Aakar Dermatology | Dr. Rajan Tajhya Skin Clinic', 'Laser Hair Reduction / Removal is a procedure that uses a beam of light to remove unwanted hair. Cost of laser hair removal start from 2000.', 0, 1, 30, '2026-09-18 20:10:23', '2026-10-03 11:11:06'),
(5, 'PRP Therapy​ - Dr.Rajan Tajhya | Aakar Dermatology', 'prp-therapy', 'skin', 'skin', 'services/prp-therapy-5b7c186eac329957.png', 'Transform your beauty with PRP Therapy at Dr Rajan Clinic.&#039;Vampire Facial&#039; enhances hair growth and skin health, starting at Rs. 4,000.', '<div><!-- primary start -->\r\n\r\n						\n<article>\n\n	<div>\n\n		<img width=\"640\" height=\"229\" src=\"http://localhost:8000/storage/services/prp-therapy-5b7c186eac329957.png\" alt=\"PRP Therapy​\" title=\"PRP Therapy​\" srcset=\"http://localhost:8000/storage/services/prp-therapy-5b7c186eac329957.png 1024w, http://localhost:8000/storage/services/prp-therapy-efbd90e4f65e64f0.png 300w, http://localhost:8000/storage/services/prp-therapy-42aa4f6e419b9040.png 768w, http://localhost:8000/storage/services/prp-therapy-443178b04ade0e04.png 1120w\">\n		<header>\n			<h3>PRP Therapy​</h3>		</header><!-- .entry-header -->\n\n				<div>\n						<section>\n						<div>\n					<div>\n			<div>\n						<div>\n				<div>\n									<div>\n					<div>\n				<div>\n										<div><div></div><div><div></div></div></div>				</div>\n							</div>\n				</div>\n								</div>\n				</div>\n					</div>\n		</div>\n					</div>\n		</section>\n				<section>\n						<div>\n					<div>\n			<div>\n						<div>\n				<div>\n									<p>In Platelets Rich Plasma Therapy, the patient’s own blood is collected and the blood plasma is separated by a centrifuge. This plasma has many growth properties and is beneficial for human cells. </p><p>PRP Therapy is helpful in treating hair fall problems and to stimulate collagen production in the skin. In simple words, collagen is a substance that is vital for skin health and beauty. Thus, PRP Therapy helps in hair regeneration and treats skin problems like acne scar, melasma, wrinkles, and dull skin.</p><p>PRP Therapy with micro-needling is the most common procedure in our clinic.</p><p>PRP therapy is also commonly known as ‘Vampire Facial’. This is because the patient’s own plasma is extracted from the blood and injected into the skin or hair follicles using Derma-roller or micro-needling. The process is completely safe, and our treatment provider at <span>Dr. Rajan Tajhya’s clinic </span>will take the utmost care of you during the procedure. </p><h2>Does Platelet-Rich Plasma Therapy have any side effects?</h2><p>There have been no serious side effects of PRP treatment recorded so far. PRP is created using your body’s own regenerative blood factors, so there is no risk of an allergic reaction.</p><p>Nevertheless, your treatment provider will see if you have any problem with the anesthetic that is applied on the scalp before injecting the platelets.</p><p>After the procedure, people might feel a little bit of tightness and discomfort, but within 30 minutes it’s pretty much done.</p><h2>Is PRP treatment a permanent solution to hair loss? When will Platelet-Rich Therapy bring results?</h2><p>Unlike other hair-fall remedies, PRP is a simple non-surgical procedure. Its effectiveness has been recorded in numerous scientific researches.</p><p>In general, you will be given three sessions in an approximate span of a month. Then, the next series of sessions are needed for only about four to six months.</p><p>The exact schedule of your treatment plan might depend on factors like the amount of hair loss you’re dealing with, as well as your age, hormones, and genetic makeup. The simplest treatment procedure has three sessions in a span of three months.</p><p>PRP doesn’t deliver results immediately, so don’t expect to see a full head of hair the next morning. The first result that you’ll witness is decreased hair shedding, followed by early regrowth and increased hair length.</p><h2>Is this procedure painful?</h2><p>At <a href=\"https://drrajanskinclinic.com/\">Dr. Rajan Clinic</a>, we’ve had some patients go through it and it’s quick and over. However, the scalp is a sensitive area. This is why for most of us normal people, PRP treatment might hurt a bit.</p><p>However, the bright part is that PRP treatment has little downtime, which means that after about an hour or so, you can go on with your usual routine. However, avoid hair-coloring, hair-washing, and scalp massage for the next 48 hours. After that, you are free to live your own life the way you like.</p><h2>How much will PRP Treatment cost in Kathmandu? What is the usual price for Platelet-Rich Therapy (PRP Treatment) in Nepal?</h2><p>Compared to other hair-fall remedies, Platelet-Rich Plasma Therapy falls in the intermediate range when it comes to pricing.</p><p>If you are looking forward to getting a PRP treatment in Kathmandu, Nepal, the entire package with PRP treatment and <a href=\"https://akarshanskin.com/our-services/prp-hair-treatment-in-nepal/\">micro-needling</a> costs only Rs. 6000. Meanwhile, if you only take micro-needling, it’ll cost you Rs 4000.</p><p><span>Dr. Rajan Tajhya’s Clinic</span> primary focus is to always cater to the needs of its clients, i.e. to serve you in the best way.</p><h2>With your best interests in consideration, here are our prices:</h2><div><table><tbody><tr><td><b>PRP Microneedling (Vampire Facial)</b></td><td><b>Rs.6,000</b></td></tr></tbody></table></div>								</div>\n				</div>\n					</div>\n		</div>\n					</div>\n		</section>\n				</div>\n		\n	</div><!-- .entry-content -->\n\n	</article><!-- #post-2845 -->\n\r\n					</div>', 'PRP Therapy​ - Dr.Rajan Tajhya | Aakar Dermatology | Dr. Rajan Tajhya Skin Clinic', 'Transform your beauty with PRP Therapy at Dr Rajan Clinic.&#039;Vampire Facial&#039; enhances hair growth and skin health, starting at Rs. 4,000.', 0, 1, 32, '2026-09-18 20:10:23', '2026-10-03 11:11:22'),
(6, 'Laser Facial Treatment', 'laser-facial', 'laser', 'laser-face', 'services/laser-facial.webp', 'Rejuvenate your skin with targeted laser facial treatments that reduce pigmentation, fine lines, and improve overall tone.', '<p>Laser facial treatments at Aakar Dermatology address a wide range of skin concerns including hyperpigmentation, sun damage, acne scars, fine lines, and uneven skin tone. Our advanced laser systems deliver precise energy to targeted areas, stimulating collagen production and skin renewal.</p><p>The result is brighter, smoother, and more youthful-looking skin with minimal downtime.</p>', 'Laser Facial Treatment Lalitpur | Skin Rejuvenation | Aakar Dermatology', 'Advanced laser facial treatments for pigmentation, acne scars & skin rejuvenation at Aakar Dermatology. Safe, effective & tailored for you.', 1, 1, 6, '2026-09-18 20:10:23', '2026-09-19 00:38:36'),
