INSERT INTO `services` (`id`, `title`, `slug`, `category`, `icon`, `image`, `short_description`, `full_description`, `meta_title`, `meta_description`, `is_featured`, `is_active`, `sort_order`, `created_at`, `updated_at`) VALUES
(8, 'Skin Problems​ - Dr.Rajan Tajhya | Aakar Dermatology', 'skin-problems', 'skin', 'skin', 'services/skin-problems-46edffd1ec57645e.png', 'Get expert solution for all skin problems, including mole removal, acne treatment, and fungal infections. Trust our experienced dermatologist.', '<div>\r\n\r\n\r\n\r\n\r\n	<a href=\"#content\">\r\n		Skip to content		\r\n	</a>\r\n\r\n	\n	\n		\n			\n				\n					\n\n						\n		\n\n			<ul>\n				\n				 	<li>\n						<a href=\"https://www.facebook.com/Drrajantajhyaskinclinic\">\n							\n								\n							\n							\n								Facebook							\n						</a>\n					</li>	\n					\n						#top-social-left li:hover a.social_links_header_0,\n						#top-social-left li:focus a.social_links_header_0 {\n						    background: #3b5998;\n						}\n					\n\n				 	\n				 	<li>\n						<a href=\"https://www.instagram.com/dr.rajan.skin.laser/\">\n							\n								\n							\n							\n								Instagram							\n						</a>\n					</li>	\n					\n						#top-social-left li:hover a.social_links_header_1,\n						#top-social-left li:focus a.social_links_header_1 {\n						    background: #00acee;\n						}\n					\n\n				 	\n				 	<li>\n						<a href=\"https://www.linkedin.com/in/dr-rajan-tajhya-427924283/?originalSubdomain=np\">\n							\n								\n							\n							\n								Linkedin							\n						</a>\n					</li>	\n					\n						#top-social-left li:hover a.social_links_header_2,\n						#top-social-left li:focus a.social_links_header_2 {\n						    background: #ea3a7e;\n						}\n					\n\n				 	\n				 	<li>\n						<a href=\"https://www.youtube.com/@drrajantajhyasskinlasercli2463\">\n							\n								\n							\n							\n								Youtube							\n						</a>\n					</li>	\n					\n						#top-social-left li:hover a.social_links_header_3,\n						#top-social-left li:focus a.social_links_header_3 {\n						    background: #cd201f;\n						}\n					\n\n				 									\n			\n			</ul>\n\n		\n\n		\n					\n					\n						\n		                   	<ul>	                   		\n		                   				<li>\n				\n\n				 +977 9813903982\n						\n		</li>\n				<li>\n			\n				 dr.rajantajhyaskinclinic@gmail.com\n				\n		</li>\n				<li>\n						\n				 Kathmandu, Nepal\n					</li>\n				                   	</ul>\n	                    \n					\n				\n			\n		\n	\n\n	\r\n	\r\n    \r\n\r\n        \r\n\r\n            \r\n\r\n            	\r\n\r\n	            	\r\n\r\n		                \n	<a href=\"https://drrajanskinclinic.com/\">\n\n    	\n        	<img src=\"http://localhost:8000/storage/services/skin-problems-46edffd1ec57645e.png\" alt=\"Logo\">\n\n        	\n    </a>\n\n	<ul><li><a href=\"https://drrajanskinclinic.com/about-dr-rajan-tajhyas-skin-clinic/\">About</a></li>\n<li><a href=\"https://drrajanskinclinic.com/our-services/\">Our Services</a></li>\n<li><a href=\"https://drrajanskinclinic.com/package-price/\">Package &amp; Price</a></li>\n<li><a href=\"https://drrajanskinclinic.com/contact-us/\">Contact Us</a></li>\n\n		    <li>\n		    	    	\n	<a href=\"https://drrajanskinclinic.com/book-an-appointment/\">\n		Get Appointment	</a>\n        \n    		    </li>\n\n	    	</ul>\r\n		                \r\n		                				            	\r\n		            	\r\n\r\n		            \r\n\r\n		        \r\n\r\n            \r\n\r\n               \r\n\r\n     \r\n\r\n\r\n	\r\n\r\n\r\n	\r\n\r\n		\r\n\r\n			\r\n\r\n				\r\n\r\n							\n						\n						\n					\n			\n						\n				\n									\n					\n				\n														\n							\n				\n								\n				\n					\n		\n					\n		\n				\n						\n					\n			\n						\n				\n									<h2>Types of skin problems</h2><p>A complete solution to all your skin problems. Acne, mole, warts, skin tags, corn, fugal infections, wrinkles, melasma, and many more</p><h2>1. Mole removal </h2><p>The procedure for mole removal depends on the size of the mole and the color of the skin. If it is a bigger mole, we might have to do cosmetic surgery. Meanwhile, smaller moles can be removed by cautery laser and pen.</p><h2>2. Freckles removal</h2><h2>3. Wart/ Skin tag/ Corn removal</h2><h3>Skin warts: </h3><p>Warts are skin growths that are caused by the human papillomavirus (HPV).</p><h3>Skin tag: </h3><p>Skin tags are painless, noncancerous growths on the skin. They’re connected to the skin by a small, thin stalk called a peduncle. Skin tags are common in both men and women, especially after age 50. They can appear anywhere on your body, though they’re commonly found in places where your skin folds such as the neck and armpits.</p><h3>Skin corn: </h3><p>Corns and calluses are thick, hardened layers of skin that develop when your skin tries to protect itself against friction and pressure. They most often develop on the feet and toes or hands and fingers. They are usually caused by bad shoes, uncomfortable soles, etc.</p><p>All these skin complications can be treated by an experienced <a href=\"https://akarshanskin.com/our-services/best-hospital-for-dermatology/\">dermatologist</a> in our clinic.</p><h2>4. Skin cancer surgery</h2><p>Unwanted lesions in the skin can be an indication of skin cancer. In order to confirm whether the unwanted growth in your skin is cancerous (or not), we perform a detailed biopsy and send the Histology for confirmation.</p><p>The marks left by such incidences may be removed <a href=\"https://drrajanskinclinic.com/\">in our clinic</a>.</p><h2>5. Treatment of skin conditions like fungal infections, allergies, drug reactions</h2>								\n				\n					\n		\n					\n		\n				\n		\r\n				\r\n\r\n			\r\n\r\n		\r\n\r\n	\r\n\r\n\r\n\r\n\n	\n\n	    \n\n	    			    	\n			        <ul><li><a href=\"https://www.facebook.com/Drrajantajhyaskinclinic\"></a></li><li><a href=\"https://www.instagram.com/dr.rajan.skin.laser/\"></a></li><li><a href=\"https://www.linkedin.com/in/dr-rajan-tajhya-427924283/?originalSubdomain=np\"></a></li><li><a href=\"https://www.youtube.com/@drrajantajhyasskinlasercli2463\"></a></li></ul>		        \n		        \n	        <ul><li><a href=\"https://drrajanskinclinic.com/about-dr-rajan-tajhyas-skin-clinic/\">About</a></li>\n<li><a href=\"https://drrajanskinclinic.com/best-dermatologist-nepal-dr-rajan-babu-tajhya/\">Best Dermatologist in Nepal: Expert Skin Care with Dr. Rajan Babu Tajhya</a></li>\n<li><a href=\"https://drrajanskinclinic.com/book-an-appointment/\">Book An Appointment</a></li>\n<li><a href=\"https://drrajanskinclinic.com/contact-us/\">Contact Us</a></li>\n<li><a href=\"https://drrajanskinclinic.com/best-skin-doctor-nepal-dr-rajan-tajhya-advanced-dermatology/\">Find the Best Skin Doctor in Nepal: Dr. Rajan Tajhya’s Advanced Dermatology Clinic</a></li>\n<li><a href=\"https://drrajanskinclinic.com/best-skin-doctor-advanced-dermatology-treatments/\">Find the Best Skin Doctor: Advanced Dermatology Treatment &amp; Skin Care Solutions</a></li>\n<li><a href=\"https://drrajanskinclinic.com/\">Home</a></li>\n<li><a href=\"https://drrajanskinclinic.com/home-copy/\">Home – Copy</a></li>\n<li><a href=\"https://drrajanskinclinic.com/our-services/\">Our Services</a></li>\n<li><a href=\"https://drrajanskinclinic.com/package-price/\">Package &amp; Price</a></li>\n<li><a href=\"https://drrajanskinclinic.com/top-dermatologist-in-nepal-advanced-skin-treatments/\">Top Dermatologist in Nepal: Advanced Skin Treatments by Dr. Rajan Tajhya</a></li>\n</ul>\n\n	        <p>\n	            Copyright ©2026 \n				\n		Dr.Rajan Tajhya | Aakar Dermatology\n		. All rights reserved. Design and Developed  by <a href=\"https://reverhub.com/\">Rever Hub Pvt. Ltd.</a>\n\n\n	    	        </p>\n	    \n	\n\n	\r\n\r\n	\r\n		\r\n			\n    	\n    		\n    		\n    	    	\n    			<a>\r\n				\r\n			</a>\r\n		\r\n	\r\n\r\n\r\n\r\n\r\n    <a></a>\r\n\r\n\r\n\r\n\n{\"prefetch\":[{\"source\":\"document\",\"where\":{\"and\":[{\"href_matches\":\"/*\"},{\"not\":{\"href_matches\":[\"/wp-*.php\",\"/wp-admin/*\",\"/wp-content/uploads/*\",\"/wp-content/*\",\"/wp-content/plugins/*\",\"/wp-content/themes/medical-business/*\",\"/wp-content/themes/bizberg/*\",\"/*\\\\?(.+)\"]}},{\"not\":{\"selector_matches\":\"a[rel~=\\\"n