(26, 'doctor_name', 'Dr. Rajan Tajhya', 'text', 'about', 'Doctor Name', '2026-09-18 20:10:23', '2026-10-08 09:42:23'),
(27, 'doctor_title', 'Founder & Lead Dermatologist, Aakar Dermatology', 'text', 'about', 'Doctor Title', '2026-09-18 20:10:23', '2026-10-08 09:42:23'),
(28, 'doctor_bio', 'Dr. Rajan Tajhya\'s journey in dermatology spans over a decade in hospital settings, where he developed deep expertise as a specialist in LASER and Dermato-surgery. Now, with the founding of Aakar Dermatology, he has reached a new milestone—creating a practice where advanced surgical and laser expertise meets compassionate, personalized care. Every procedure, from complex hair transplants to precise eyelid surgeries, reflects his commitment to helping you achieve results that transform not just your appearance, but your confidence.', 'textarea', 'about', 'Doctor Bio', '2026-09-18 20:10:23', '2026-10-08 09:42:23'),
(29, 'doctor_photo', 'settings/doctor-photo.png', 'image', 'about', 'Doctor Photo (800×1000 px portrait, 4:5 ratio)', '2026-09-18 20:10:23', '2026-09-19 00:38:35'),
(30, 'cta_heading', 'Begin Your Journey with Aakar', 'text', 'cta', 'CTA Heading', '2026-09-18 20:10:23', '2026-10-08 09:42:23'),
(31, 'cta_subheading', 'Whether you\'re dealing with a skin concern or exploring aesthetic enhancements, we are here to help. Schedule your consultation today and discover the difference personalized, expert care can make.', 'textarea', 'cta', 'CTA Subheading', '2026-09-18 20:10:23', '2026-10-08 09:42:23'),
