-- Table structure for table `testimonials`
--

CREATE TABLE `testimonials` (
  `id` bigint(20) UNSIGNED NOT NULL,
  `patient_name` varchar(255) NOT NULL,
  `patient_photo` varchar(255) DEFAULT NULL,
  `treatment` varchar(255) DEFAULT NULL,
  `review` text NOT NULL,
  `rating` tinyint(4) NOT NULL DEFAULT 5,
  `source` varchar(255) NOT NULL DEFAULT 'google',
  `is_featured` tinyint(1) NOT NULL DEFAULT 0,
  `is_active` tinyint(1) NOT NULL DEFAULT 1,
  `sort_order` int(11) NOT NULL DEFAULT 0,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

--
-- Dumping data for table `testimonials`
--

INSERT INTO `testimonials` (`id`, `patient_name`, `patient_photo`, `treatment`, `review`, `rating`, `source`, `is_featured`, `is_active`, `sort_order`, `created_at`, `updated_at`) VALUES
(1, 'Sita Sharma', NULL, 'Acne Treatment', 'I struggled with acne for years and tried countless products with no success. Dr. Rajan\'s personalized treatment plan cleared my skin within 3 months. I finally feel confident in my own skin. The clinic is clean, professional, and the staff is incredibly kind.', 5, 'google', 1, 1, 1, '2026-09-18 20:10:23', '2026-09-18 20:10:23'),
(2, 'Ramesh Adhikari', NULL, 'Hair Transplant', 'I was going bald at 32 and it really affected my confidence. Dr. Rajan performed my hair transplant and the results are incredible—so natural looking! I\'m 6 months post-op and very happy with the outcome. Highly recommend Aakar Dermatology for hair restoration.', 5, 'google', 1, 1, 2, '2026-09-18 20:10:23', '2026-09-18 20:10:23'),
(3, 'Priya Maharjan', NULL, 'Laser Facial', 'The laser facial treatment at Aakar completely transformed my skin. My dark spots have faded significantly and my skin tone is so much more even. Dr. Rajan explained every step of the process and made me feel comfortable throughout.', 5, 'google', 1, 1, 3, '2026-09-18 20:10:23', '2026-09-18 20:10:23'),
(4, 'Binod Karki', NULL, 'PRP Therapy', 'After noticing significant hair thinning, I consulted Dr. Rajan and he recommended PRP therapy. After 4 sessions, I can see new hair growth and my existing hair is much thicker. The doctor is very knowledgeable and explains everything clearly.', 5, 'facebook', 1, 1, 4, '2026-09-18 20:10:23', '2026-09-18 20:10:23'),
(5, 'Anita Thapa', NULL, 'Eyelid Surgery', 'I had heavy drooping eyelids that made me look tired all the time. Dr. Rajan\'s blepharoplasty completely changed my appearance. The recovery was smooth and the results are absolutely natural. I look more refreshed and awake. Thank you!', 5, 'google', 0, 1, 5, '2026-09-18 20:10:23', '2026-09-18 20:10:23'),
(6, 'Sunil Bajracharya', NULL, 'Laser Hair Removal', 'Best decision I ever made! Laser hair removal at Aakar was painless and the results are permanent. I\'ve completed 6 sessions and my skin is completely smooth. The staff is very professional and the clinic maintains high hygiene standards.', 5, 'google', 0, 1, 6, '2026-09-18 20:10:23', '2026-09-18 20:10:23');

