INSERT INTO `why_choose_us` (`id`, `title`, `description`, `icon`, `is_active`, `sort_order`, `created_at`, `updated_at`) VALUES
(1, 'Personalized Treatment Plans', 'We don\'t believe in one-size-fits-all solutions. Every treatment plan is customized to your unique skin type, concerns, lifestyle, and aesthetic goals.', 'personalized', 1, 1, '2026-09-18 20:10:23', '2026-09-18 20:10:23'),
(2, 'Advanced Technology', 'We utilize proven, modern dermatological equipment and techniques to deliver safe, effective results you can see and feel.', 'technology', 1, 2, '2026-09-18 20:10:23', '2026-09-18 20:10:23'),
(3, 'Convenient & Accessible', 'Say goodbye to crowded waiting rooms and rushed appointments. We\'ve created a clinic environment that respects your time while giving you the attention you deserve.', 'accessible', 1, 3, '2026-09-18 20:10:23', '2026-09-18 20:10:23'),
(4, 'Proven Results', 'Our track record speaks for itself. Patients trust us for transformative results that look natural, feel authentic, and boost confidence from the inside out.', 'results', 1, 4, '2026-09-18 20:10:23', '2026-09-18 20:10:23');

