UPDATE `services`
SET
  `title` = CASE `slug`
    WHEN 'acne-and-acne-scar-removal' THEN 'Acne and Acne Scar Removal'
    WHEN 'asian-eyelid-surgery-or-blepharoplasty' THEN 'Asian Eyelid Surgery or Blepharoplasty'
    WHEN 'black-doll-laser' THEN 'Black Doll Laser'
    WHEN 'botox-injection' THEN 'Botox Injection'
    WHEN 'chemical-peeling' THEN 'Chemical Peeling'
