    WHEN 'hair-transplant' THEN 'Hair Transplant'
    WHEN 'hydra-facial' THEN 'Hydra Facial'
    WHEN 'laser-hair-reduction' THEN 'Laser Hair Reduction'
    WHEN 'laser-tattoo-removal' THEN 'Laser Tattoo Removal'
    WHEN 'prp-therapy' THEN 'PRP Therapy'
    WHEN 'scar-revision-surgery' THEN 'Scar Revision Surgery'
    WHEN 'skin-and-dermatology-consultation' THEN 'Skin and Dermatology Consultation'
    WHEN 'skin-problems' THEN 'Skin Problems'
    WHEN 'ultherapy-facelift' THEN 'Ultherapy Facelift'
    WHEN 'wrinkle-reduction' THEN 'Wrinkle Reduction'
  END,
  `meta_title` = CASE `slug`
    WHEN 'acne-and-acne-scar-removal' THEN 'Acne and Acne Scar Removal | Aakar Dermatology'
    WHEN 'asian-eyelid-surgery-or-blepharoplasty' THEN 'Asian Eyelid Surgery or Blepharoplasty | Aakar Dermatology'
    WHEN 'black-doll-laser' THEN 'Black Doll Laser | Aakar Dermatology'
    WHEN 'botox-injection' THEN 'Botox Injection | Aakar Dermatology'
    WHEN 'chemical-peeling' THEN 'Chemical Peeling | Aakar Dermatology'
    WHEN 'diode-laser-hair-removal' THEN 'Diode Laser Hair Removal | Aakar Dermatology'
    WHEN 'hair-transplant' THEN 'Hair Transplant | Aakar Dermatology'
    WHEN 'hydra-facial' THEN 'Hydra Facial in Nepal | Aakar Dermatology'
    WHEN 'laser-hair-reduction' THEN 'Laser Hair Reduction | Aakar Dermatology'
    WHEN 'laser-tattoo-removal' THEN 'Laser Tattoo Removal | Aakar Dermatology'
    WHEN 'prp-therapy' THEN 'PRP Therapy | Aakar Dermatology'
    WHEN 'scar-revision-surgery' THEN 'Scar Revision Surgery | Aakar Dermatology'
    WHEN 'skin-and-dermatology-consultation' THEN 'Skin and Dermatology Consultation | Aakar Dermatology'
    WHEN 'skin-problems' THEN 'Skin Problems | Aakar Dermatology'
    WHEN 'ultherapy-facelift' THEN 'Ultherapy Facelift | Aakar Dermatology'
    WHEN 'wrinkle-reduction' THEN 'Wrinkle Reduction | Aakar Dermatology'
  END,
  `meta_description` = CASE `slug`
    WHEN 'acne-and-acne-scar-removal' THEN 'Explore acne and acne scar treatments in Nepal. At Dr. Rajan Tajhya’s clinic. Get expert advice for healthier skin!'
    WHEN 'asian-eyelid-surgery-or-blepharoplasty' THEN 'Achieve fuller, bigger eyes with Asian Eyelid Surgery in Nepal. This one-hour procedure offers a permanent solution for easier eyeliner.'
    WHEN 'black-doll-laser' THEN 'Black Doll Laser procedure at Dr. Rajan Clinic in Nepal. This non-invasive treatment reduces signs of aging, and promotes collagen.'
    WHEN 'botox-injection' THEN 'Discover safe and effective Botox Injection treatments at Dr. Rajan Tajhya Clinic in Kathmandu. Reduce wrinkles and fine lines.'
    WHEN 'chemical-peeling' THEN 'Revitalize your skin with chemical peels at Dr Rajan Clinic in Nepal. Achieve smoother skin for just Rs. 2,000 per session.'
    WHEN 'diode-laser-hair-removal' THEN 'Achieve smooth, hair-free skin with Diode Laser Hair Removal at Dr Rajan Clinic in Lalitpur, Kathmandu. Affordable sessions start at Rs. 2,500'
    WHEN 'hair-transplant' THEN 'Restore your hair with advanced Hair Transplant services at Dr. Rajan Tajhya Clinic in Nepal. And get the best results.'
    WHEN 'hydra-facial' THEN 'Revitalize your skin with HydraFacial treatment at Dr Rajan Clinic in Lalitpur. Enjoy glowing, hydrated skin, suitable for all skin types!'
    WHEN 'laser-hair-reduction' THEN 'Laser Hair Reduction / Removal is a procedure that uses a beam of light to remove unwanted hair. Cost of laser hair removal start from 2000.'
    WHEN 'laser-tattoo-removal' THEN 'Laser tattoo removal is the process where ink particles break down after exposure to a beam of light. cost start from Nrs 2500.'
    WHEN 'prp-therapy' THEN 'Transform your beauty with PRP Therapy at Dr Rajan Clinic. ''Vampire Facial'' enhances hair growth and skin health, starting at Rs. 4,000.'
    WHEN 'scar-revision-surgery' THEN 'Reduce scars by 80-90% at our Lalitpur clinic. Our expert dermatologist offers quick, effective scar removal starting at Rs. 3,000 per cm.'
    WHEN 'skin-and-dermatology-consultation' THEN 'At Dr. Rajan Tajhya''s Skin Laser Clinic, we offer expert solutions for skin issues, including psoriasis, acne, and mole removal.'
    WHEN 'skin-problems' THEN 'Get expert solution for all skin problems, including mole removal, acne treatment, and fungal infections. Trust our experienced dermatologist.'
    WHEN 'ultherapy-facelift' THEN 'Revitalize your skin with a non-invasive Ultherapy facelift in Lalitpur, Kathmandu. Reduce wrinkles and enhance your jawline without surgery.'
    WHEN 'wrinkle-reduction' THEN 'Revitalize your youth at Dr. Rajan Tajhya’s clinic in Lalitpur, Kathmandu. Explore effective wrinkle treatments.'
  END
WHERE `slug` IN (
  'acne-and-acne-scar-removal', 'asian-eyelid-surgery-or-blepharoplasty',
  'black-doll-laser', 'botox-injection', 'chemical-peeling',
  'diode-laser-hair-removal', 'hair-transplant', 'hydra-facial',
  'laser-hair-reduction', 'laser-tattoo-removal', 'prp-therapy',
  'scar-revision-surgery', 'skin-and-dermatology-consultation',
  'skin-problems', 'ultherapy-facelift', 'wrinkle-reduction'
);

